IMPLEMENTATION_SENTINEL_SHOULD_NEVER_APPEAR = True

def deliver(client, store, delivery):
    for attempt in range(3):
        try:
            response = client.post(
                delivery.endpoint,
                json=delivery.payload,
                headers={"X-Delivery-ID": delivery.delivery_id},
            )
            store.record_attempt(delivery.delivery_id, response.status_code)
            return response
        except TimeoutError:
            if attempt == 2:
                raise

